const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Denmark geometry
  const denmark = ee.Geometry.Rectangle([8.0, 54.5, 15.2, 57.8]);

  // 2. Time periods
  const date2017Start = '2017-07-01';
  const date2017End = '2017-07-31';
  const date2018Start = '2018-07-01';
  const date2018End = '2018-07-31';

  // 3. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 5. Get Sentinel-2 data for July 2017
  let col2017 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(denmark)
    .filterDate(date2017Start, date2017End)
    .map(maskClouds)
    .map(addNDVI);

  const size2017 = await col2017.size().getInfo();
  console.log('2017 July images:', size2017);

  if (size2017 === 0) {
    console.log('No images found for July 2017');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Get Sentinel-2 data for July 2018
  let col2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(denmark)
    .filterDate(date2018Start, date2018End)
    .map(maskClouds)
    .map(addNDVI);

  const size2018 = await col2018.size().getInfo();
  console.log('2018 July images:', size2018);

  if (size2018 === 0) {
    console.log('No images found for July 2018');
    console.log('<answer>C1</answer>');
    return;
  }

  // 7. Calculate median NDVI composites
  const ndvi2017 = col2017.select('NDVI').median();
  const ndvi2018 = col2018.select('NDVI').median();

  // 8. Calculate statistics with pixel count check
  const stats2017 = await ndvi2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: denmark,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2017 = stats2017.NDVI_mean;
  const count2017 = stats2017.NDVI_count;

  console.log('2017 Stats - Mean NDVI:', mean2017, 'Pixels:', count2017);

  if (count2017 === 0 || count2017 === null) {
    console.log('No valid pixels for 2017 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  const stats2018 = await ndvi2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: denmark,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2018 = stats2018.NDVI_mean;
  const count2018 = stats2018.NDVI_count;

  console.log('2018 Stats - Mean NDVI:', mean2018, 'Pixels:', count2018);

  if (count2018 === 0 || count2018 === null) {
    console.log('No valid pixels for 2018 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Validation
  if (mean2017 === null || mean2018 === null || 
      isNaN(mean2017) || isNaN(mean2018) ||
      mean2017 < -1 || mean2017 > 1 || 
      mean2018 < -1 || mean2018 > 1) {
    console.log('Invalid NDVI values detected');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Final comparison
  const ndviChange = mean2018 - mean2017;
  console.log('NDVI Change (2018-2017):', ndviChange.toFixed(4));

  // Browning increase means NDVI decreased (more browning in 2018)
  if (mean2018 < mean2017) {
    console.log('Vegetation browning increased in July 2018');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation browning did not increase in July 2018');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
